// Copies chunks from an async source into a sink.
export async function pump(source, sink, opts = {}) {
  const signal = opts.signal;
  let written = 0;

  function raceWithSignal(promise, sig) {
    if (!sig) return Promise.resolve(promise);
    if (sig.aborted) return Promise.reject(sig.reason);
    return new Promise((resolve, reject) => {
      const onAbort = () => {
        reject(sig.reason);
      };
      sig.addEventListener('abort', onAbort, { once: true });
      Promise.resolve(promise).then(
        (v) => {
          sig.removeEventListener('abort', onAbort);
          resolve(v);
        },
        (e) => {
          sig.removeEventListener('abort', onAbort);
          reject(e);
        }
      );
    });
  }

  try {
    while (true) {
      if (signal?.aborted) {
        throw signal.reason;
      }
      const nextResult = await raceWithSignal(source.next(), signal);
      if (nextResult.done) break;
      if (signal?.aborted) {
        throw signal.reason;
      }
      await raceWithSignal(sink.write(nextResult.value), signal);
      written++;
    }
    if (signal?.aborted) {
      throw signal.reason;
    }
    await raceWithSignal(sink.close(), signal);
    return { written };
  } catch (err) {
    try {
      await source.return();
    } catch (_) {}
    try {
      await sink.abort(err);
    } catch (_) {}
    throw err;
  }
}

