    if (signal?.aborted) throw signal.reason;

    await sink.close();

    if (signal && abortListener) {
      try { signal.removeEventListener('abort', abortListener); } catch {}
    }

    return { written };
  } catch (err) {
    if (signal && abortListener) {
      try { signal.removeEventListener('abort', abortListener); } catch {}
    }
    try {
      const r = source.return();
      if (r && typeof r.catch === 'function') r.catch(() => {});
      await r;
    } catch {}
    try {
      const a = sink.abort(err);
      if (a && typeof a.catch === 'function') a.catch(() => {});
      await a;
    } catch {}
    throw err;
  }
